207	// mega_vit_sg2_tc — the DEDICATED SuperGrok2 ViT TC launcher (twin of
208	// mega_decoder_sg2_tc). Binds the SG2 meta-net state slices + the HBM weight bundle
209	// + per-tensor scalar arrays, dispatches launch_fused_vit_megakernel_tc<SuperGrok2>.
210	// State layout: [m | v | mu | loss | sharpness | slow | gru_state(total*GH)].
211	cudaError_t mega_vit_sg2_tc(
212	        PersistentContext ctx, float* params,
213	        const float* patches, const int* targets, int B,
214	        float* state, float* grad, float* loss_out,
215	        const float* input_proj_W, const float* input_proj_b,
216	        const float* csa_q_W, const float* csa_k_W, const float* csa_v_W, const float* csa_out_W,
217	        const float* csa_compress_w, const float* csa_idx_DQ, const float* csa_idx_K,
218	        const float* hca_q_W, const float* hca_k_W, const float* hca_v_W, const float* hca_out_W,
219	        const float* gru_Wz, const float* gru_bz, const float* gru_Wr, const float* gru_br,
220	        const float* gru_Wh, const float* gru_bh,
221	        const float* peer_query_Ws, const float* prod_keys_A, const float* prod_keys_B,
222	        const float* expert_W1, const float* expert_b1, const float* expert_W2, const float* expert_b2,
223	        const float* sc_alpha, const float* sc_gru_decay, const float* sc_lamb_eff,
224	        const float* sc_beta1, const float* sc_bc1, const float* sc_bc2,
225	        float rescale, float beta2, float lr, float wd, float eps,
226	        float rho, float sam_on,
227	        int step, cudaStream_t stream, int ncta_cap) {
228	    const int64_t total = kVitTotalElems;
229	    const int T = B * vit::kSeq;
230	
231	    int dev = 0;
232	    cudaError_t err = cudaGetDevice(&dev);
233	    if (err != cudaSuccess) return err;
234	    int n_sms = 1;
235	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
236	    if (err != cudaSuccess) return err;
237	    int nCTA = n_sms;
238	    if (ncta_cap > 0 && ncta_cap < nCTA) nCTA = ncta_cap;
239	
240	    const int64_t need = vit_tc_workspace_floats(T, B, nCTA);
241	    VitTcLauncherScratch& sc = vit_tc_launcher_scratch(dev, need);
242	    ctx.g_next_task  = sc.g_next;
243	    ctx.g_arrived    = sc.g_arrived;
244	    ctx.g_generation = sc.g_generation;
245	    ctx.n_tasks      = kVitNumTensors;
246	
247	    FusedOptState st;
248	    st.exp_avg     = state;
249	    st.exp_avg_sq  = state + total;
250	    st.mu          = state + 2 * total;
251	    float* sharp_base = loss_out + 1;             // state + 3*total + 1
252	    st.sharpness   = sharp_base;
253	    st.sg2_slow    = sharp_base + total;
254	    st.sg2_gru_state = st.sg2_slow + total;
255	    st.sg2_input_proj_W = input_proj_W; st.sg2_input_proj_b = input_proj_b;
256	    st.sg2_csa_q_W = csa_q_W; st.sg2_csa_k_W = csa_k_W; st.sg2_csa_v_W = csa_v_W;
257	    st.sg2_csa_out_W = csa_out_W; st.sg2_csa_compress_w = csa_compress_w;
258	    st.sg2_csa_idx_DQ = csa_idx_DQ; st.sg2_csa_idx_K = csa_idx_K;
259	    st.sg2_hca_q_W = hca_q_W; st.sg2_hca_k_W = hca_k_W; st.sg2_hca_v_W = hca_v_W;
260	    st.sg2_hca_out_W = hca_out_W;
261	    st.sg2_gru_Wz = gru_Wz; st.sg2_gru_bz = gru_bz; st.sg2_gru_Wr = gru_Wr;
262	    st.sg2_gru_br = gru_br; st.sg2_gru_Wh = gru_Wh; st.sg2_gru_bh = gru_bh;
263	    st.sg2_peer_query_Ws = peer_query_Ws; st.sg2_prod_keys_A = prod_keys_A;
264	    st.sg2_prod_keys_B = prod_keys_B;
265	    st.sg2_expert_W1 = expert_W1; st.sg2_expert_b1 = expert_b1;
266	    st.sg2_expert_W2 = expert_W2; st.sg2_expert_b2 = expert_b2;
267	    st.sg2_alpha = sc_alpha; st.sg2_gru_decay = sc_gru_decay; st.sg2_lamb_eff = sc_lamb_eff;
268	    st.sg2_beta1 = sc_beta1; st.sg2_bc1 = sc_bc1; st.sg2_bc2 = sc_bc2;
269	    st.sg2_rescale = rescale;
270	    st.beta2 = beta2; st.lr = lr; st.wd = wd; st.eps = eps;
271	    st.rho = rho;
272	    st.looksam_sam = sam_on;
273	
274	    ViTInputCtx in;
275	    in.patches   = patches;
276	    in.targets   = targets;
277	    in.B         = B;
278	    in.workspace = sc.workspace;
279	    in.loss_out  = loss_out;
280	
281	    return launch_fused_vit_megakernel_tc<OptId::SuperGrok2>(
282	        ctx, params, in, grad, lr, step, st, stream, nCTA);
283	}
284	
285	}}}  // namespace sg::fused::sm90
