937	        pw.muon_AX           = pw.muon_X   + kVitMuonMaxNumel;
938	        pw.muon_AAX          = pw.muon_AX  + kVitMuonMaxNumel;
939	        pw.muon_orth         = pw.muon_AAX + kVitMuonMaxNumel;
940	        pw.muon_A            = pw.muon_orth + kVitMuonMaxNumel;
941	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)kVitMuonMaxRows * kVitMuonMaxRows;
942	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
943	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
944	        const int   ns_steps = 5;                 // bindings.cpp default
945	        for (int mi = 0; mi < vittc::kVitNumMuon2D; ++mi) {
946	            const vittc::VitMuon2D M = vittc::vit_muon_2d(mi);   // was kVitMuon2D[mi]
947	            const int rows = M.rows, cols = M.cols;
948	            const int64_t numel = (int64_t)rows * cols;
949	            const int64_t off   = (int64_t)kVitOffsets[M.tidx];
950	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
951	            pw.muon_buf = st.exp_avg + off;
952	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
