954	            bar.sync();
955	            muon_norm_reduce_phaseB(ctx, pw);
956	            bar.sync();
957	            muon_scale_X(numel, pw);
958	            bar.sync();
959	            // NS iterations. After each combine, orth holds the new iterate; swap so
960	            // the next iteration reads it as X. ns_steps swaps → final result is in
