2096	    for (int si = 0; si < nsamp; ++si) {
2097	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
2098	        const float* hlast = sc.finalin + (int64_t)rlast * dec::kD;
2099	        float sum = 0.0f;
2100	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += hlast[j];
2101	        float mean = dec_block_sum(sum, red) / (float)dec::kD;
2102	        float vs = 0.0f;
2103	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) { float c = hlast[j] - mean; vs += c * c; }
2104	        float var = dec_block_sum(vs, red) / (float)dec::kD;
2105	        float iv = rsqrtf(var + dec::kLnEps);
2106	        if (threadIdx.x == 0) sc.fni[rlast] = iv;
2107	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
2108	            float xh = (hlast[j] - mean) * iv;
2109	            sc.fnx[(int64_t)rlast * dec::kD + j] = xh;
2110	            float hn = xh * w.norm_w[j] + w.norm_b[j];
2111	            acts.X_hn[(int64_t)si_global(g0, si) * dec::kD + j] = __float2bfloat16(hn);
2112	        }
2113	        __syncthreads();
2114	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
2115	        const __nv_bfloat16* hnb = acts.X_hn + (int64_t)si_global(g0, si) * dec::kD;
2116	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
2117	            const float* Wr = w.out_w + (int64_t)o * dec::kD;
2118	            float acc = w.out_b[o];
2119	            #pragma unroll 4
2120	            for (int k = 0; k < dec::kD; ++k) acc += __bfloat162float(hnb[k]) * Wr[k];
2121	            lg[o] = acc;
2122	        }
2123	        __syncthreads();
2124	        int tgt = tgt_ids[si_global(g0, si)];
2125	        float lmax = -CUDART_INF_F;
2126	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
2127	        lmax = dec_block_max(lmax, red);
2128	        float es = 0.0f;
2129	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
2130	        es = dec_block_sum(es, red);
2131	        float logz = lmax + __logf(es);
2132	        if (threadIdx.x == 0) nll_acc += (logz - lg[tgt]);
2133	        __syncthreads();
2134	    }
2135	    return nll_acc;
2136	}
