2138	// TP-aware backward tile (mirror of dectc_backward_tile with the two backward
2139	// reduce points ②' (ff0 dX) and ①' (in_proj dX) wrapped in if constexpr).
2140	template <class Par = ::sg::fused::par::SingleGPU,
2141	          class Transport = ::sg::fused::sm90::tp::LoopbackTransport>
2142	__device__ void dectc_backward_tile_impl(
2143	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, bool active, int B,
2144	        const DecActs& acts,
2145	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
2146	        float* __restrict__ lnvec, float* __restrict__ work2,
2147	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red,
2148	        const Transport& tr, const ::sg::fused::GridBarrier& bar,
2149	        int64_t slot_pub, int64_t slot_red,
2150	        unsigned long long* pipeBars = nullptr) {
2151	    (void)active; (void)slot_red;
2152	    const int nsamp = nrows / dec::kSeq;
2153	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
2154	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
2155	    for (int li = 0; li < dec::kLayers; ++li) {
2156	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
2157	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
2158	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
2159	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
2160	    }
2161	    float* gn_normw = lnvec + (int64_t)(4 * dec::kLayers + 0) * dec::kD;
2162	    float* gn_normb = lnvec + (int64_t)(4 * dec::kLayers + 1) * dec::kD;
2163	
2164	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
2165	    __syncthreads();
2166	    for (int si = 0; si < nsamp; ++si) {
2167	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
2168	        const int gs = si_global(g0, si);
2169	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
2170	        int tgt = tgt_ids[gs];
2171	        float lmax = -CUDART_INF_F;
2172	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
2173	        lmax = dec_block_max(lmax, red);
2174	        float es = 0.0f;
2175	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
2176	        es = dec_block_sum(es, red);
2177	        float inv_es = 1.0f / es;
2178	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
2179	            float smo = __expf(lg[o] - lmax) * inv_es;
2180	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
2181	            lg[o] = dl;
2182	            acts.dY_logits[(int64_t)gs * dec::kVocab + o] = __float2bfloat16(dl);
2183	        }
2184	        __syncthreads();
2185	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
2186	            float dhn = 0.0f;
2187	            for (int o = 0; o < dec::kVocab; ++o)
2188	                dhn += lg[o] * w.out_w[(int64_t)o * dec::kD + j];
2189	            sc.work[(int64_t)rlast * dec::kD + j] = dhn;
2190	        }
2191	        __syncthreads();
2192	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
2193	            float dhn = sc.work[(int64_t)rlast * dec::kD + j];
2194	            float xh = sc.fnx[(int64_t)rlast * dec::kD + j];
2195	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
2196	        }
2197	        __syncthreads();
2198	        {
2199	            const float* dyr = sc.work + (int64_t)rlast * dec::kD;
2200	            const float* xhr = sc.fnx + (int64_t)rlast * dec::kD;
2201	            float sda = 0.0f, sdax = 0.0f;
2202	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
2203	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
2204	            }
2205	            sda = dec_block_sum(sda, red); sdax = dec_block_sum(sdax, red);
2206	            float iv = sc.fni[rlast];
2207	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
2208	                float dxhat = dyr[j] * w.norm_w[j];
2209	                sc.dh[(int64_t)rlast * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
2210	            }
2211	            __syncthreads();
2212	        }
2213	    }
2214	
2215	    for (int li = dec::kLayers - 1; li >= 0; --li) {
2216	        const DecWeights::Layer& L = w.layer[li];
2217	        const int ff0_nout = Par::kTPComm ? dec::kDff / Par::kTP : dec::kDff;
2218	        const int qkv_nout = Par::kTPComm ? (3 * dec::kD) / Par::kTP : 3 * dec::kD;
2219	        dectc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
2220	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
2221	            work2[idx] = sc.work[idx];
2222	            acts.dY_ff2[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);
2223	        }
2224	        __syncthreads();
2225	        // ff2 dX (ROW-parallel ff2 ⇒ dgact is the rank's local [nrows, dff/P], comm-free).
2226	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * dec::kD, wb.ff2_wT[li],
2227	                                           sc.work, dec::kDff, ff0_nout, sA, sB, pipeBars);  // dgact [nrows,dff/P]
2228	        __syncthreads();
2229	        for (int idx = threadIdx.x; idx < nrows * ff0_nout; idx += blockDim.x) {
2230	            float dff0 = sc.work[idx] * dec_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
2231	            sc.work[idx] = dff0;
2232	            acts.dY_ff0[li][(int64_t)g0 * ff0_nout + idx] = __float2bfloat16(dff0);
2233	        }
2234	        __syncthreads();
2235	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32
2236	        //   → sc.x1 (free now — fwd x1 consumed); then add to work2.
2237	        if constexpr (!Par::kTPComm) {
2238	            dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * dec::kDff, wb.ff0_wT[li],
2239	                                               sc.x1, /*Kin=*/dec::kD, /*Nout=*/dec::kDff, sA, sB, pipeBars);  // dx1_ffn [nrows,d]
2240	        } else {
2241	            // COLUMN-parallel ff0: ff0_wT[li] is the rank's [dff/P, d] col-shard's
2242	            // transpose; dY_ff0 is the rank's own [nrows, dff/P]. The dX is a PARTIAL
2243	            // (Σ_pe) → publish [nrows,d] → reduce → sc.x1 (②' of design §5.1). Then
2244	            // the `work2[idx] += sc.x1[idx]` accumulate below runs unchanged.
2245	            const int Noutloc = dec::kDff / tr.n_pes();
2246	            if (active) {
2247	                ::sg::fused::sm90::tp::tp_colparallel_dx_partial_tile<SG_TUNED_TILE_N>(
2248	                    tr, slot_pub,
2249	                    /*dYown=*/ acts.dY_ff0[li] + (int64_t)g0 * Noutloc, wb.ff0_wT[li],
2250	                    /*Kin=*/ dec::kD, /*Nout_local=*/ Noutloc, sA, sB);
2251	            }
2252	            tr.rendezvous(bar);
2253	            ::sg::fused::sm90::tp::tp_allreduce_sum_fixed_order(
2254	                tr, slot_pub, sc.x1, (int64_t)nrows * dec::kD, threadIdx.x, blockDim.x);
2255	            tr.rendezvous(bar);
2256	        }
2257	        __syncthreads();
2258	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
2259	            work2[idx] += sc.x1[idx];
2260	        __syncthreads();
2261	        dectc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
2262	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
2263	            sc.dh[idx] = sc.work[idx];
2264	            acts.dY_a[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);
2265	        }
2266	        __syncthreads();
2267	        // out_proj dX (ROW-parallel out_proj ⇒ dctx is the rank's local [nrows, d/P], comm-free).
2268	        const int dctx_nin = Par::kTPComm ? dec::kD / Par::kTP : dec::kD;
2269	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * dec::kD, wb.out_wT[li],
2270	                                           sc.work, dctx_nin, dec::kD, sA, sB, pipeBars);  // dctx [nrows, d/P]
2271	        __syncthreads();
2272	        // attention bwd (full-width on this path; head-local shard is the §6 8-GPU touch).
2273	        dectc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
2274	        for (int idx = threadIdx.x; idx < nrows * qkv_nout; idx += blockDim.x)
2275	            acts.dY_qkv[li][(int64_t)g0 * qkv_nout + idx] = __float2bfloat16(work2[idx]);
2276	        __syncthreads();
2277	        // in_proj dX: dx_in_attn = dqkv @ in_w  (output width Kin=d, contract Nout=3d).
2278	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
2279	        if constexpr (!Par::kTPComm) {
2280	            dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * dec::kD, wb.in_wT[li],
2281	                                               sc.work, /*Kin=*/dec::kD, /*Nout=*/3 * dec::kD, sA, sB, pipeBars);  // dx_in_attn
2282	        } else {
2283	            // COLUMN(QKV)-parallel in_proj: in_wT[li] is the rank's [3d/P, d] qkv
2284	            // col-shard's transpose; dY_qkv is the rank's own [nrows, 3d/P] (the
2285	            // 3-block q|k|v own-rows concatenated). The dX is a PARTIAL → publish
2286	            // [nrows,d] → reduce → sc.work (①' of design §5.1). Then the residual
2287	            // add `sc.dh[idx] += sc.work[idx]` below runs unchanged.
2288	            const int Noutloc = (3 * dec::kD) / tr.n_pes();
2289	            if (active) {
2290	                ::sg::fused::sm90::tp::tp_colparallel_dx_partial_tile<SG_TUNED_TILE_N>(
2291	                    tr, slot_pub,
2292	                    /*dYown=*/ acts.dY_qkv[li] + (int64_t)g0 * Noutloc, wb.in_wT[li],
2293	                    /*Kin=*/ dec::kD, /*Nout_local=*/ Noutloc, sA, sB);
2294	            }
2295	            tr.rendezvous(bar);
2296	            ::sg::fused::sm90::tp::tp_allreduce_sum_fixed_order(
2297	                tr, slot_pub, sc.work, (int64_t)nrows * dec::kD, threadIdx.x, blockDim.x);
2298	            tr.rendezvous(bar);
2299	        }
2300	        __syncthreads();
2301	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
2302	            sc.dh[idx] += sc.work[idx];
2303	        __syncthreads();
2304	    }
2305	
2306	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
2307	        acts.dh0[(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.dh[idx]);
2308	    __syncthreads();
2309	}
