2339	// ════════════════════════════════════════════════════════════════════════
2340	//  SAM-cell-scoped OUT-OF-LINE tile shims (reg-pressure campaign C2 -- the
2341	//  mamba precedent, model_stage_mamba_tc.cuh mbtc_forward_tile/backward_tile,
2342	//  SCOPED).  The SAM-coupled cells (LookSAM/SG11/SG15/SG2) run the heavy tile
2343	//  fwd+bwd TWICE per step (P1 + the P2.4 SAM 2nd pass); inlining both copies
2344	//  into one kernel blows the 255-reg budget by ~15 KB of hot-loop spills.
2345	//  Routing BOTH passes of those cells through these __noinline__ shims gives
2346	//  one shared out-of-line frame (measured: total spill bytes roughly halve and
2347	//  leave the entry body nearly clean).  The single-pass cells keep calling the
2348	//  inline bodies directly -- their allocation (255 regs, ZERO spills) is
2349	//  byte-identical to the pre-campaign engine, never taxed with an ABI boundary.

831	    //    HERE in the P1 window so it overlaps the other CTAs' fwd/bwd and the
832	    //    already-present B1 barrier fences it before the P2 consume — NO new barrier.
833	    //    cta 0 then joins P1. The build is O(T), parallel over its worker lanes, so
834	    //    it measures ~0.3 ms (≪ P1) — far below the embed-consume time it unlocks. ──
835	    if (cta == 0)
836	        dectc::dectc_embed_build_lists(tok.tokens, T, embed_row_start, embed_perm);
837	
838	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
839	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
840	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
841	    const int nrows_tile = dectc::kTileM;
842	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
843	    float nll_acc = 0.0f;
844	#ifdef SG_DEC_PROFILE
845	    unsigned long long prof_fwd = 0, prof_bwd = 0;
846	#endif
847	    if constexpr (!Par::kTPComm) {
848	        // ░░ DEFAULT / SingleGPU path — BYTE-IDENTICAL to the pre-Par kernel. ░░
849	        for (int ti = cta; ti < n_tiles; ti += nCTA) {
850	            const int g0 = ti * nrows_tile;
851	            const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
852	#ifdef SG_DEC_PROFILE
853	            __syncthreads(); unsigned long long _c0 = clock64();
854	#endif
855	            float nll;
856	            if constexpr (kSamCoupled)
857	                nll = dectc::dectc_forward_tile_outlined(w, wb, g0, nrows, acts, sc, tok.tokens,
858	                                                         tok.targets, sm.sA, sm.sB, sm.red SG_DEC_PIPE_BARS_ARG);
859	            else
860	                nll = dectc::dectc_forward_tile(w, wb, g0, nrows, acts, sc, tok.tokens, tok.targets,
861	                                                sm.sA, sm.sB, sm.red SG_DEC_PIPE_BARS_ARG);
862	#ifdef SG_DEC_PROFILE
863	            __syncthreads(); unsigned long long _c1 = clock64();
864	#endif
865	            if constexpr (kSamCoupled)
866	                dectc::dectc_backward_tile_outlined(w, wb, g0, nrows, B, acts, sc, tok.targets,
867	                                                    my_lnvec, sc.work2, sm.sA, sm.sB, sm.red SG_DEC_PIPE_BARS_ARG);
868	            else
869	                dectc::dectc_backward_tile(w, wb, g0, nrows, B, acts, sc, tok.targets,
870	                                           my_lnvec, sc.work2, sm.sA, sm.sB, sm.red SG_DEC_PIPE_BARS_ARG);
871	#ifdef SG_DEC_PROFILE
872	            __syncthreads(); unsigned long long _c2 = clock64();
873	            if (threadIdx.x == 0) { prof_fwd += _c1 - _c0; prof_bwd += _c2 - _c1; }
874	#endif
875	            if (threadIdx.x == 0) nll_acc += nll;
876	            __syncthreads();
877	        }
878	    } else {
879	        // ░░ kTPComm path — GRID-LOCKSTEP so tr.rendezvous(bar) at the 4 reduce
880	        //    points (model_stage_decoder_tc.cuh ①/②/①'/②') is reached the SAME
881	        //    number of times by every CTA on this GPU (§1 deadlock fix). All CTAs
882	        //    of THIS GPU cooperate on the SAME tile each round; the tile fns thread
883	        //    <Par,Transport> + (tr, bar, slot) so the reduce fires inside fwd/bwd.
884	        //
885	        //    ROUND COUNT is GRID-UNIFORM: the activations are REPLICATED across TP
886	        //    ranks (TP shards WEIGHTS, not the batch), so every PE/GPU sees the
887	        //    SAME T ⇒ SAME n_tiles ⇒ SAME n_rounds. The loopback (P virtual PEs in
888	        //    ONE grid) and the real multi-GPU (P grids) BOTH satisfy this.
889	        //
890	        //    The two slot offsets (publish / reduced) are this CTA's lane in the
891	        //    symmetric heap: slot_base = (cta_within_pe) * 2 * tp_tile_slot_floats.
892	        auto tr = ::sg::fused::sm90::tp::make_transport_from_comm<Par>(comm);
893	        const int P            = tr.n_pes();
894	        const int ctas_per_pe  = nCTA / P;                 // launcher asserts nCTA % P == 0
895	        const int cta_in_pe    = ::sg::fused::sm90::tp::LoopbackTransport::cta_within_pe(cta, nCTA, P);
