862	    // B1 sub-tile: nrows = kSeq·S is generally not a multiple of 64 → the linear
863	    // GEMMs issue ceil(nrows/64) m64 atoms and guard pad rows with m_real=nrows.
864	    const int m_atoms_rt = (nrows + wgs::kWgmmaAtomM - 1) / wgs::kWgmmaAtomM;
865	#endif
866	    const int npatch_rows = nsamp * vit::kNPatch;
867	    const int gp0 = (g0 / vit::kSeq) * vit::kNPatch;   // first PATCH row of this tile
868	    // ── Stage this tile's patches into X_patch (bf16) as patch token rows.
869	    //    Sample si's patch p is global patch row gp0 + si*kNPatch + p; the source
870	    //    is patches[(g0/kSeq + si)*kNPatch*kPatch + p*kPatch + c]. ──
871	    for (int idx = threadIdx.x; idx < npatch_rows * vit::kPatch; idx += blockDim.x) {
872	        const int pr = idx / vit::kPatch, c = idx % vit::kPatch;
873	        const int si = pr / vit::kNPatch, p = pr % vit::kNPatch;
874	        const int gs = si_global(g0, si);
875	        float v = patches[((int64_t)gs * vit::kNPatch + p) * vit::kPatch + c];
876	        acts.X_patch[(int64_t)(gp0 + pr) * vit::kPatch + c] = __float2bfloat16(v);
877	    }
878	    __syncthreads();
879	    // ── patch_proj: proj[pr, :] = X_patch[pr,:49] @ patch_w[d,49]ᵀ + patch_b.
880	    //    fp32 → sc.work (patch rows). K=49 padded to 64 (one m64 atom block per
881	    //    64 patch rows). M = npatch_rows (= nsamp*16) issued as ceil/64 atoms. ──
882	    {
883	        const int pm_atoms = (npatch_rows + wgs::kWgmmaAtomM - 1) / wgs::kWgmmaAtomM;
884	        const __nv_bfloat16* Xp = acts.X_patch + (int64_t)gp0 * vit::kPatch;
885	        // fwd into sc.work [npatch_rows, d] fp32 (Kpad=64, Kreal=49).
886	        const int Kpad = ((vit::kPatch + wgs::kWgmmaAtomK - 1) / wgs::kWgmmaAtomK) * wgs::kWgmmaAtomK; // 64
887	        const int N = SG_TUNED_TILE_N;
888	        const int k_steps = Kpad / wgs::kWgmmaAtomK;
889	        for (int n0 = 0; n0 < vit::kD; n0 += N) {
890	            const int n_real = (vit::kD - n0) < N ? (vit::kD - n0) : N;
891	            auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
892	                return k < vit::kPatch ? Xp[(int64_t)m * vit::kPatch + k] : __float2bfloat16(0.f); };
893	            auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
894	                int nn = n0 + n; return (nn < vit::kD && k < vit::kPatch) ? __float2bfloat16(w.patch_w[(int64_t)nn * vit::kPatch + k]) : __float2bfloat16(0.f); };
895	            auto out  = [&] (int m, int n, float v) { sc.work[(int64_t)m * vit::kD + n0 + n] = v; };
896	            tc_gemm_block_unpipelined<SG_TUNED_TILE_N, /*MaxAtomsM=*/kAtomsM>(
897	                0, pm_atoms, n_real, k_steps SG_VIT_PATCH_MREAL_ARG, srcA, srcB, out, sA, sB);
898	        }
899	    }
900	    __syncthreads();
901	    // ── Build X_in[0]: CLS rows (pos 0 of each sample) = cls + pos[0]; patch
902	    //    rows (pos 1+i) = proj(patch_i) + pos[1+i]. bf16. ──
903	    for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
904	        const int r = idx / vit::kD, j = idx % vit::kD;
905	        const int g = g0 + r;
906	        const int sp = g % vit::kSeq;            // position within the sample
907	        float v;
908	        if (sp == 0) {
909	            v = w.cls[j] + w.pos[j];             // CLS + pos[0]
910	        } else {
911	            const int si = r / vit::kSeq;
912	            const int p = sp - 1;                // patch index 0..15
913	            const int pr = si * vit::kNPatch + p;
914	            v = sc.work[(int64_t)pr * vit::kD + j] + w.pos[(int64_t)sp * vit::kD + j] + w.patch_b[j];
915	        }
916	        acts.X_in[0][(int64_t)g * vit::kD + j] = __float2bfloat16(v);
917	    }
918	    __syncthreads();
919	
920	    for (int li = 0; li < vit::kLayers; ++li) {
921	        const VitWeights::Layer& L = w.layer[li];
922	        const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * vit::kD;        // [nrows,d]
923	        // qkv = Xin @ in_w^T + in_b   (N=3d, K=d). bf16 → scratch.qkv[li].
924	        vittc_gemm_fwd<SG_TUNED_TILE_N>(Xin, L.in_w, sc.qkv[li], vit::kD, vit::kD, 3 * vit::kD, SG_VIT_P1_BF16_MA_MR, sA, sB);
925	        __syncthreads();
926	        // add in_b (the fwd GEMM did W only; biases folded in scalar here for qkv).
927	        for (int idx = threadIdx.x; idx < nrows * 3 * vit::kD; idx += blockDim.x) {
928	            const int j = idx % (3 * vit::kD);
929	            float v = __bfloat162float(sc.qkv[li][idx]) + L.in_b[j];
930	            sc.qkv[li][idx] = __float2bfloat16(v);
931	        }
932	        __syncthreads();
933	        // attention (FULL) → ctx (work fp32) + attn[li] weights.
934	        vittc_attn_fwd_tile(sc.qkv[li], nrows, sc.work, sc.attn[li]);
935	        // ctx bf16 → X_ctx[li] (out_proj input + its dW operand).
936	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
937	            const int r = idx / vit::kD, j = idx % vit::kD;
938	            acts.X_ctx[li][(int64_t)(g0 + r) * vit::kD + j] = __float2bfloat16(sc.work[(int64_t)r * vit::kD + j]);
939	        }
940	        __syncthreads();
941	        // a = X_ctx @ out_w^T (+ out_b). fp32 → work.
942	        vittc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_ctx[li] + (int64_t)g0 * vit::kD, L.out_w,
943	                                            sc.work, vit::kD, vit::kD SG_VIT_P1_F32_MA_MR, sA, sB);
944	        __syncthreads();
945	        // r1 = Xin + a + out_b → work (fp32).
946	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
947	            const int r = idx / vit::kD, j = idx % vit::kD;
948	            sc.work[(int64_t)r * vit::kD + j] += __bfloat162float(Xin[(int64_t)r * vit::kD + j]) + L.out_b[j];
949	        }
950	        __syncthreads();
951	        // n1(r1) → x1 (fp32) + caches[li]; then bf16 → X_x1[li].
952	        vittc_ln_fwd_tile(sc.work, L.n1_w, L.n1_b, nrows, sc.x1, sc.n1x[li], sc.n1i[li], red);
953	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
954	            const int r = idx / vit::kD, j = idx % vit::kD;
955	            acts.X_x1[li][(int64_t)(g0 + r) * vit::kD + j] = __float2bfloat16(sc.x1[(int64_t)r * vit::kD + j]);
956	        }
957	        __syncthreads();
958	        // ff0 = X_x1 @ ff0_w^T (+ ff0_b). fp32 → work; pre-gelu bf16 → ff0pre;
959	        // gelu(pre+b) → X_gact[li] (bf16).
960	        vittc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_x1[li] + (int64_t)g0 * vit::kD, L.ff0_w,
961	                                            sc.work, vit::kD, vit::kDff SG_VIT_P1_F32_MA_MR, sA, sB);
962	        __syncthreads();
963	        for (int idx = threadIdx.x; idx < nrows * vit::kDff; idx += blockDim.x) {
964	            const int r = idx / vit::kDff, j = idx % vit::kDff;
965	            float pre = sc.work[(int64_t)r * vit::kDff + j] + L.ff0_b[j];
966	            sc.ff0pre[li][(int64_t)r * vit::kDff + j] = __float2bfloat16(pre);
967	            acts.X_gact[li][(int64_t)(g0 + r) * vit::kDff + j] = __float2bfloat16(vit_gelu(pre));
968	        }
969	        __syncthreads();
970	        // ff2 = X_gact @ ff2_w^T (+ ff2_b). fp32 → work.
971	        vittc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_gact[li] + (int64_t)g0 * vit::kDff, L.ff2_w,
972	                                            sc.work, vit::kDff, vit::kD SG_VIT_P1_F32_MA_MR, sA, sB);
973	        __syncthreads();
974	        // r2 = x1 + ff2 + ff2_b → work (fp32).
975	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
976	            const int r = idx / vit::kD, j = idx % vit::kD;
977	            sc.work[(int64_t)r * vit::kD + j] += sc.x1[(int64_t)r * vit::kD + j] + L.ff2_b[j];
978	        }
979	        __syncthreads();
980	        if (li + 1 < vit::kLayers) {
981	            // n2(r2) → finalin (fp32 reused) + n2 caches[li]; bf16 → X_in[li+1].
982	            vittc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
983	            for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
984	                const int r = idx / vit::kD, j = idx % vit::kD;
985	                acts.X_in[li + 1][(int64_t)(g0 + r) * vit::kD + j] = __float2bfloat16(sc.finalin[(int64_t)r * vit::kD + j]);
986	            }
987	            __syncthreads();
988	        } else {
989	            // last layer: n2(r2) → finalin (fp32, all positions; head reads pos 0).
990	            vittc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
991	        }
992	    }
993	
994	    // ── Final norm + head + CE, scalar PER-SAMPLE on the CLS position (0) only.
995	    //    DELTA 3: CLS at pos 0 (row si*kSeq), not the last position. ──
996	    float nll_acc = 0.0f;
997	#ifdef SG_VIT_PROFILE
998	    __syncthreads(); unsigned long long _ha = (threadIdx.x == 0) ? clock64() : 0;
999	#endif
1000	    for (int si = 0; si < nsamp; ++si) {
1001	        const int rcls = si * vit::kSeq;                  // CLS row (pos 0)
1002	        const float* hcls = sc.finalin + (int64_t)rcls * vit::kD;
1003	        float sum = 0.0f;
1004	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) sum += hcls[j];
1005	        float mean = vit_block_sum(sum, red) / (float)vit::kD;
1006	        float vs = 0.0f;
1007	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) { float c = hcls[j] - mean; vs += c * c; }
1008	        float var = vit_block_sum(vs, red) / (float)vit::kD;
1009	        float iv = rsqrtf(var + vit::kLnEps);
1010	        if (threadIdx.x == 0) sc.fni[rcls] = iv;
1011	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
1012	            float xh = (hcls[j] - mean) * iv;
1013	            sc.fnx[(int64_t)rcls * vit::kD + j] = xh;
1014	            float hn = xh * w.norm_w[j] + w.norm_b[j];
1015	            acts.X_hn[(int64_t)si_global(g0, si) * vit::kD + j] = __float2bfloat16(hn);
1016	        }
1017	        __syncthreads();
1018	        // logits[o] = hn · out_w[o] + out_b[o]  (scalar; hn read from X_hn bf16).
1019	        float* lg = sc.logits + (int64_t)si * vit::kVocab;
1020	        const __nv_bfloat16* hnb = acts.X_hn + (int64_t)si_global(g0, si) * vit::kD;
1021	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
1022	            const float* Wr = w.out_w + (int64_t)o * vit::kD;
1023	            float acc = w.out_b[o];
1024	            #pragma unroll 4
1025	            for (int k = 0; k < vit::kD; ++k) acc += __bfloat162float(hnb[k]) * Wr[k];
1026	            lg[o] = acc;
1027	        }
1028	        __syncthreads();
1029	        int tgt = tgt_ids[si_global(g0, si)];
1030	        float lmax = -CUDART_INF_F;
1031	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
1032	        lmax = vit_block_max(lmax, red);
1033	        float es = 0.0f;
1034	        for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
1035	        es = vit_block_sum(es, red);
1036	        float logz = lmax + __logf(es);
1037	        if (threadIdx.x == 0) nll_acc += (logz - lg[tgt]);
1038	        __syncthreads();
1039	    }
1040	#ifdef SG_VIT_PROFILE
1041	    __syncthreads();
1042	    if (threadIdx.x == 0) atomicMax(&g_vit_prof_head[0], clock64() - _ha);
1043	#endif
1044	    return nll_acc;
1045	}
