1047	// Attention BACKWARD over a tile (FULL — no causal triangle). Reads qkv (bf16),
1048	// attn weights, dctx [nrows,d] fp32; writes dqkv [nrows,3d] fp32 into `dqkv_out`.
1049	// dsc is the per-CTA dscores scratch. Mirror of vit_backward_sample's attention
1050	// (A: dv, B: dscores, C: dq/dk), looped over samples. scale = 1/sqrt(dh).
1051	__device__ __forceinline__ void vittc_attn_bwd_tile(
1052	        const __nv_bfloat16* __restrict__ qkv, const float* __restrict__ attn_w,
1053	        const float* __restrict__ dctx, int nrows,
1054	        float* __restrict__ dqkv_out, float* __restrict__ dsc) {
1055	    const int nsamp = nrows / vit::kSeq;
1056	    const float scale = vit::attn_scale();
1057	    // A: dv[kj] = Σ_{qi} attn[qi,kj] * dctx[qi].  Owner: (sample,kj,head,t). FULL.
1058	    for (int r = threadIdx.x; r < nsamp * vit::kSeq * vit::kHeads * vit::kDhead; r += blockDim.x) {
1059	        const int si  = r / (vit::kSeq * vit::kHeads * vit::kDhead);
1060	        int rem = r % (vit::kSeq * vit::kHeads * vit::kDhead);
1061	        const int kj  = rem / (vit::kHeads * vit::kDhead);
1062	        rem = rem % (vit::kHeads * vit::kDhead);
1063	        const int hh  = rem / vit::kDhead, t = rem % vit::kDhead;
1064	        const int qoff = hh * vit::kDhead;
1065	        const int rbase = si * vit::kSeq;
1066	        const float* aw = attn_w + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq) * vit::kSeq;  // [S,S]
1067	        float acc = 0.0f;
1068	        #pragma unroll
1069	        for (int qi = 0; qi < vit::kSeq; ++qi)   // FULL: all qi
1070	            acc += aw[qi * vit::kSeq + kj] * dctx[(int64_t)(rbase + qi) * vit::kD + qoff + t];
1071	        dqkv_out[(int64_t)(rbase + kj) * 3 * vit::kD + 2 * vit::kD + qoff + t] = acc;   // dv block
1072	    }
1073	    __syncthreads();
1074	    // B: dscores ds[qi,kj] = attn*(datt - Σ_k datt*attn)*scale (FULL, all kj).
1075	    //    datt[kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t]. Owner: (sample,head,qi).
1076	    for (int r = threadIdx.x; r < nsamp * vit::kHeads * vit::kSeq; r += blockDim.x) {
1077	        const int si = r / (vit::kHeads * vit::kSeq);
1078	        int rem = r % (vit::kHeads * vit::kSeq);
1079	        const int hh = rem / vit::kSeq, qi = rem % vit::kSeq;
1080	        const int qoff = hh * vit::kDhead;
1081	        const int rbase = si * vit::kSeq;
1082	        const float* aw = attn_w + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq) * vit::kSeq;
1083	        float datt[vit::kSeq];
1084	        #pragma unroll
1085	        for (int kj = 0; kj < vit::kSeq; ++kj) {
1086	            float acc = 0.0f;
1087	            #pragma unroll
1088	            for (int t = 0; t < vit::kDhead; ++t)
1089	                acc += dctx[(int64_t)(rbase + qi) * vit::kD + qoff + t]
1090	                     * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * vit::kD + 2 * vit::kD + qoff + t]);
1091	            datt[kj] = acc;
1092	        }
1093	        float dot = 0.0f;
1094	        #pragma unroll
1095	        for (int kj = 0; kj < vit::kSeq; ++kj) dot += datt[kj] * aw[qi * vit::kSeq + kj];
1096	        float* ds = dsc + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq + qi) * vit::kSeq;
1097	        #pragma unroll
1098	        for (int kj = 0; kj < vit::kSeq; ++kj) {
1099	            float a = aw[qi * vit::kSeq + kj];
1100	            ds[kj] = a * (datt[kj] - dot) * scale;
1101	        }
1102	    }
1103	    __syncthreads();
1104	    // C: dq[qi]=Σ_kj ds[qi,kj]*k[kj]; dk[kj]=Σ_qi ds[qi,kj]*q[qi]. FULL. Owner: (sample,pos,head,t).
1105	    for (int r = threadIdx.x; r < nsamp * vit::kSeq * vit::kHeads * vit::kDhead; r += blockDim.x) {
1106	        const int si = r / (vit::kSeq * vit::kHeads * vit::kDhead);
1107	        int rem = r % (vit::kSeq * vit::kHeads * vit::kDhead);
1108	        const int pos = rem / (vit::kHeads * vit::kDhead);
1109	        rem = rem % (vit::kHeads * vit::kDhead);
1110	        const int hh = rem / vit::kDhead, t = rem % vit::kDhead;
1111	        const int qoff = hh * vit::kDhead;
1112	        const int rbase = si * vit::kSeq;
1113	        const float* ds = dsc + ((int64_t)(si * vit::kHeads + hh) * vit::kSeq) * vit::kSeq;  // [S,S]
1114	        float dq = 0.0f, dk = 0.0f;
1115	        #pragma unroll
1116	        for (int kj = 0; kj < vit::kSeq; ++kj) {
1117	            dq += ds[pos * vit::kSeq + kj] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * vit::kD + vit::kD + qoff + t]);
1118	            dk += ds[kj * vit::kSeq + pos] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * vit::kD + qoff + t]);
1119	        }
1120	        dqkv_out[(int64_t)(rbase + pos) * 3 * vit::kD + qoff + t] = dq;             // dq block
1121	        dqkv_out[(int64_t)(rbase + pos) * 3 * vit::kD + vit::kD + qoff + t] = dk;   // dk block
1122	    }
1123	    __syncthreads();
1124	}
