1126	// ════════════════════════════════════════════════════════════════════════
1127	//  BACKWARD over one TOKEN TILE. Assumes vittc_forward_tile ran for THIS tile.
1128	//  Fork B: computes dX via wgmma and WRITES the dY output-adjoints to VitActs
1129	//  (dY_qkv/dY_a/dY_ff0/dY_ff2/dY_logits) + dh0 for P2's dW — it does NOT touch
1130	//  the weight dW here. ACCUMULATES the 10 LN-vector grads into `lnvec`
1131	//  [kNumLnVec × d] (deterministic single-owner-per-j). `B` is the full batch
1132	//  (CE mean scale). DELTA 3: head/final-norm bwd on the CLS row (pos 0).
1133	// ════════════════════════════════════════════════════════════════════════
1134	__device__ void vittc_backward_tile(
1135	        const VitWeights& w, int g0, int nrows, int B, const VitActs& acts,
1136	        const VitTileScratch& sc, const int* __restrict__ tgt_ids,
1137	        float* __restrict__ lnvec, float* __restrict__ work2,
1138	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {

1138	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
1139	    const int nsamp = nrows / vit::kSeq;
1140	#if SG_TUNED_VIT_P1_SUBTILE_S < 64
1141	    // B1 sub-tile: dX GEMMs issue ceil(nrows/64) m64 atoms with m_real=nrows.
1142	    const int m_atoms_rt = (nrows + wgs::kWgmmaAtomM - 1) / wgs::kWgmmaAtomM;
1143	#endif
1144	    float* gn_n1w[vit::kLayers]; float* gn_n1b[vit::kLayers];
1145	    float* gn_n2w[vit::kLayers]; float* gn_n2b[vit::kLayers];
1146	    for (int li = 0; li < vit::kLayers; ++li) {
1147	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * vit::kD;
1148	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * vit::kD;
1149	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * vit::kD;
1150	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * vit::kD;
1151	    }
1152	    float* gn_normw = lnvec + (int64_t)(4 * vit::kLayers + 0) * vit::kD;  // 8*kD at L=2
1153	    float* gn_normb = lnvec + (int64_t)(4 * vit::kLayers + 1) * vit::kD;  // 9*kD at L=2
1154	
