        const int dctx_nin = Par::kTPComm ? vit::kD / Par::kTP : vit::kD;
        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * vit::kD, L.out_w,
                                           sc.work, dctx_nin, vit::kD, sA, sB);  // dctx [nrows, d/P]
        __syncthreads();
